INSERT INTO cms.portfolio_item (id, category_id, slug, title_en, title_ar, client_name, year, subtitle_en, subtitle_ar, price, price_note_en, price_note_ar, external_url, location) VALUES ('port-1', 'pcat-cms-1', 'saffron-table-case-1', 'Bahrain Financial Harbour Gala 500 Pax', 'وليمة حفل مرفأ البحرين المالي لـ500 ضيف', 'Al-Jazeera Gulf Holdings W.L.L.', 2025, 'Delivered for Al-Jazeera Gulf Holdings W.L.L. across Adliya with measurable SLA benchmarks.', 'تم التنفيذ لصالح مجموعة الجزيرة الخليجية القابضة في Adliya وفق أعلى معايير الجودة والالتزام.', 960, 'Turnkey scope including 10% NBR VAT compliance (BHD)', 'باقة تنفيذ متكاملة شاملة التقارير وضريبة القيمة المضافة', 'https://saffrontable.bh/work/saffron-table-case-1', 'Adliya, Bahrain') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-1', 'saffron-table-2026-outlook', 'Saffron Table 2026 GCC Market Outlook & Benchmarks', 'توقعات أسواق الخليج ومعايير الأداء لعام 2026 — مائدة الزعفران', 'Key operational benchmarks, real metrics, and 2026 guidance from Saffron Table in Adliya.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من مائدة الزعفران في Adliya.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Contemporary Bahraini kitchen and gourmet pantry crafting daily fresh dishes, specialty spice blends, and corporate catering. Focusing on Corporate Buffet Catering (50 Guests), our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"مطبخ بحريني معاصر ومتجر منتجات غذائية يقدم أطباقاً طازجة يومياً وخلطات توابل فاخرة وضيافة للشركات. من خلال خدمة ضيافة بوفيه للشركات (50 ضيفاً) نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>Contemporary Bahraini kitchen and gourmet pantry crafting daily fresh dishes, specialty spice blends, and corporate catering.</p><p>Focusing on <strong>Corporate Buffet Catering (50 Guests)</strong>, our Adliya specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>مطبخ بحريني معاصر ومتجر منتجات غذائية يقدم أطباقاً طازجة يومياً وخلطات توابل فاخرة وضيافة للشركات.</p><p>من خلال خدمة <strong>ضيافة بوفيه للشركات (50 ضيفاً)</strong>، يعمل فريقنا في Adliya على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-01.png', 'Saffron Table 2026 GCC Market Outlook & Benchmarks | Saffron Table', 'توقعات أسواق الخليج ومعايير الأداء لعام 2026 — مائدة الزعفران | مائدة الزعفران', 'Executive guide by Saffron Table covering Corporate Buffet Catering (50 Guests) benchmarks in Bahrain.', 'دليل تنفيذي من مائدة الزعفران حول معايير ضيافة بوفيه للشركات (50 ضيفاً) في البحرين.', 'Insights', '{"food","insights","Adliya","2026"}'::text[], 'Hana Yousef', 'published', now() - interval '6 days', true, now() - interval '6 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-1', 'How quickly can Saffron Table initiate a Corporate Buffet Catering (50 Guests) engagement?', 'كم يستغرق بدء تنفيذ خدمة ضيافة بوفيه للشركات (50 ضيفاً) لدى مائدة الزعفران؟', 'Discovery and kickoff begin within 48 hours of quotation sign-off, with a dedicated lead assigned in Adliya.', 'يبدأ التخطيط والتنفيذ خلال 48 ساعة من اعتماد عرض السعر مع تعيين مدير حساب مخصص في Adliya.', 'services', true, 1, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.portfolio_item (id, category_id, slug, title_en, title_ar, client_name, year, subtitle_en, subtitle_ar, price, price_note_en, price_note_ar, external_url, location) VALUES ('port-2', 'pcat-cms-2', 'saffron-table-case-2', 'Ramadan Majlis Hospitality 30-Night Program', 'برنامج ضيافة مجالس رمضان طوال الشهر', 'Bahrain Bay Hospitality Group', 2026, 'Delivered for Bahrain Bay Hospitality Group across Adliya with measurable SLA benchmarks.', 'تم التنفيذ لصالح مجموعة خليج البحرين للضيافة في Adliya وفق أعلى معايير الجودة والالتزام.', 960, 'Turnkey scope including 10% NBR VAT compliance (BHD)', 'باقة تنفيذ متكاملة شاملة التقارير وضريبة القيمة المضافة', 'https://saffrontable.bh/work/saffron-table-case-2', 'Adliya, Bahrain') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-2', 'saffron-table-service-standards', 'Inside Our Catering SLA: Speed, Quality & Auditability', 'معايير اتفاقية مستوى الخدمة والجودة في ضيافة بوفيه للشركات (50 ضيفاً)', 'Key operational benchmarks, real metrics, and 2026 guidance from Saffron Table in Adliya.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من مائدة الزعفران في Adliya.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Contemporary Bahraini kitchen and gourmet pantry crafting daily fresh dishes, specialty spice blends, and corporate catering. Focusing on Private Chef Tasting Menu, our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"مطبخ بحريني معاصر ومتجر منتجات غذائية يقدم أطباقاً طازجة يومياً وخلطات توابل فاخرة وضيافة للشركات. من خلال خدمة قائمة تذوق مع شيف خاص نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>Contemporary Bahraini kitchen and gourmet pantry crafting daily fresh dishes, specialty spice blends, and corporate catering.</p><p>Focusing on <strong>Private Chef Tasting Menu</strong>, our Adliya specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>مطبخ بحريني معاصر ومتجر منتجات غذائية يقدم أطباقاً طازجة يومياً وخلطات توابل فاخرة وضيافة للشركات.</p><p>من خلال خدمة <strong>قائمة تذوق مع شيف خاص</strong>، يعمل فريقنا في Adliya على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-02.png', 'Inside Our Catering SLA: Speed, Quality & Auditability | Saffron Table', 'معايير اتفاقية مستوى الخدمة والجودة في ضيافة بوفيه للشركات (50 ضيفاً) | مائدة الزعفران', 'Executive guide by Saffron Table covering Private Chef Tasting Menu benchmarks in Bahrain.', 'دليل تنفيذي من مائدة الزعفران حول معايير قائمة تذوق مع شيف خاص في البحرين.', 'Operations', '{"food","operations","Adliya","2026"}'::text[], 'Bader Ali', 'published', now() - interval '12 days', true, now() - interval '12 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-2', 'Do all invoices include Bahrain NBR 10% VAT and Arabic breakdown?', 'هل تشمل الفواتير ضريبة القيمة المضافة 10% والتفصيل باللغتين؟', 'Yes. Every tax invoice is issued in BHD under CR CR-152410-1 and VAT ID 200015241000002 with itemized bilingual lines.', 'نعم، تصدر جميع الفواتير الضريبية بعملة BHD وفق السجل CR-152410-1 والرقم الضريبي 200015241000002.', 'billing', true, 2, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.portfolio_item (id, category_id, slug, title_en, title_ar, client_name, year, subtitle_en, subtitle_ar, price, price_note_en, price_note_ar, external_url, location) VALUES ('port-3', 'pcat-cms-3', 'saffron-table-case-3', 'F1 Circuit Paddock Artisanal Corner', 'ركن الضيافة التراثي في حلبة البحرين الدولية', 'Dilmun Energy Partners', 2025, 'Delivered for Dilmun Energy Partners across Adliya with measurable SLA benchmarks.', 'تم التنفيذ لصالح شركاء دلمون للطاقة في Adliya وفق أعلى معايير الجودة والالتزام.', 260, 'Turnkey scope including 10% NBR VAT compliance (BHD)', 'باقة تنفيذ متكاملة شاملة التقارير وضريبة القيمة المضافة', 'https://saffrontable.bh/work/saffron-table-case-3', 'Adliya, Bahrain') ON CONFLICT (id) DO NOTHING;
