INSERT INTO cms.website_content (id, draft, published, previous, revision, published_at, updated_at) VALUES ('main', '{"company":{"nameEn":"Saffron Table Hospitality W.L.L.","nameAr":"مائدة الزعفران للضيافة ذ.م.م","shortEn":"Saffron Table","shortAr":"مائدة الزعفران","taglineEn":"Artisanal Gulf Kitchen, Pantry & Event Catering","taglineAr":"مطبخ خليجي حرفي ومنتجات غذائية وضيافة مناسبات","aboutEn":"Contemporary Bahraini kitchen and gourmet pantry crafting daily fresh dishes, specialty spice blends, and corporate catering.","aboutAr":"مطبخ بحريني معاصر ومتجر منتجات غذائية يقدم أطباقاً طازجة يومياً وخلطات توابل فاخرة وضيافة للشركات."},"hero":{"titleEn":"Saffron Table — Artisanal Gulf Kitchen, Pantry & Event Catering","titleAr":"مائدة الزعفران — مطبخ خليجي حرفي ومنتجات غذائية وضيافة مناسبات","ctaLabelEn":"Explore Saffron Table","ctaLabelAr":"استكشف مائدة الزعفران"},"banners":[{"id":"hero-1","title_en":"Saffron Table: Corporate Buffet Catering (50 Guests)","title_ar":"مائدة الزعفران: ضيافة بوفيه للشركات (50 ضيفاً)","subtitle_en":"Artisanal Gulf Kitchen, Pantry & Event Catering","subtitle_ar":"مطبخ خليجي حرفي ومنتجات غذائية وضيافة مناسبات","media_type":"image","media_url":"/api/files/media/banners/banner-01.png","poster_url":"/api/files/media/banners/banner-01.png","display_order":1,"is_active":true,"cta_label_en":"Request Proposal","cta_label_ar":"اطلب عرض سعر","cta_link":"/contact"},{"id":"hero-2","title_en":"Saffron Table: Private Chef Tasting Menu","title_ar":"مائدة الزعفران: قائمة تذوق مع شيف خاص","subtitle_en":"Artisanal Gulf Kitchen, Pantry & Event Catering","subtitle_ar":"مطبخ خليجي حرفي ومنتجات غذائية وضيافة مناسبات","media_type":"image","media_url":"/api/files/media/banners/banner-02.png","poster_url":"/api/files/media/banners/banner-02.png","display_order":2,"is_active":true,"cta_label_en":"Explore Our Work","cta_label_ar":"استعرض أعمالنا","cta_link":"/work"},{"id":"hero-3","title_en":"Saffron Table: Executive Boardroom Catering Packages","title_ar":"مائدة الزعف